        for c in range(col, -1, -1):
            if board[r][c] == char_to_move:
                start_row, start_col = r, c
                break

    # Move cells down
    for r in range(start_row, -1, -1):
        for c in range(col, -1, -1):
            if board[r][c] == char_to_move:
                board[r][c] = ' '
            elif board[r][c] == char_to_replace:
                board[r+1][c] = char_to_replace
                board[r+1][c] = ' '

    # Replace cells above with 'g'
    for r in range(start_row, -1, -1):
        for c in range(col, -1, -1):
            if board[r][c] == ' ':
                board[r][c] = char_to_replace

    # Add new 'N' at the bottom
    for c in range(col, -1, -1):
        if board[row][c] == ' ':
            board[row][c] = char_to_move

    return ["".join(row) for row in board]
